/**
 * Whether a value is a number the number formatters can show: a finite number
 * or a numeric string — not null, undefined, '', a boolean or text such as '-'.
 *
 * @param {*} value - Value to check
 * @returns {boolean} True when the value is numeric
 */
const isFormattableNumber = (value) => value !== null && value !== undefined && value !== ''
  && typeof value !== 'boolean' && Number.isFinite(Number(value));

const Utils = {
  string: {
    /**
     * Generates a random hex string from the crypto random source.
     *
     * @param {number} [length=8] - Number of random bytes; the string is twice as long
     * @returns {string} Hex string
     */
    random(length = 8) {
      return Array.from(crypto.getRandomValues(new Uint8Array(length)))
        .map(b => b.toString(16).padStart(2, '0'))
        .join('');
    },

    /**
     * Reads an API/form value as a boolean the way a PHP/MySQL backend means it:
     * '0', 'false', 'off', 'no', '' and the JS falsy values are false, anything
     * else is true. Plain Boolean() would turn the string '0' (enum('1','0')
     * columns) into true.
     *
     * @param {*} value - Value to read
     * @returns {boolean} Boolean meaning of the value
     */
    toBoolean(value) {
      if (typeof value === 'string') {
        return !['', '0', 'false', 'off', 'no', 'null', 'undefined'].includes(value.trim().toLowerCase());
      }
      return Boolean(value);
    },

    /**
     * Entity-encodes a value for safe insertion as HTML text.
     *
     * @param {*} value - Value to encode; null and undefined become an empty string
     * @returns {string} Encoded text
     */
    escape(value) {
      const s = value == null ? '' : String(value);
      return s
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
    },

    /**
     * Replaces everything outside letters, digits, dots and hyphens with an
     * underscore, so the name is safe to use as a file name.
     *
     * @param {string} filename - Name to clean
     * @returns {string} Cleaned name
     */
    sanitizeFilename(filename) {
      return filename.replace(/[^a-z0-9.-]/gi, '_');
    },

    /**
     * Upper-cases the first character and leaves the rest as it is.
     *
     * @param {string} str - Text to capitalize
     * @returns {string} Capitalized text
     */
    capitalize(str) {
      return str.charAt(0).toUpperCase() + str.slice(1);
    },

    /**
     * Convert snake_case, kebab-case, or camelCase to human-readable text
     * - snake_case (underscore) → Sentence case: 'multi_select' → 'Multi select'
     * - kebab-case (hyphen) → Title Case: 'multi-select' → 'Multi Select'
     * - camelCase → Title Case: 'firstName' → 'First Name'
     * - UPPER_CASE → Sentence case: 'UPPER_CASE' → 'Upper case'
     * @param {string} str - Input string
     * @returns {string} Humanized string
     */
    humanize(str) {
      const s = String(str);
      const hasUnderscore = s.includes('_');

      // Process the string
      let result = s
        .replace(/([a-z])([A-Z])/g, '$1 $2')  // camelCase → camel Case
        .replace(/[_-]+/g, ' ')               // separators → spaces
        .replace(/\s+/g, ' ')
        .trim();

      if (hasUnderscore) {
        // snake_case / UPPER_CASE → Sentence case
        result = result.toLowerCase();
        return result.charAt(0).toUpperCase() + result.slice(1);
      } else {
        // kebab-case / camelCase → Title Case
        return result.replace(/\b\w/g, c => c.toUpperCase());
      }
    },

    /**
     * Shortens text to a maximum length, with the ending counted inside the
     * limit so the result never exceeds it.
     *
     * @param {string} str - Text to shorten
     * @param {number} [length=100] - Maximum length of the result
     * @param {string} [ending='...'] - Suffix marking the cut
     * @returns {string} Shortened text, or the original when it already fits
     */
    truncate(str, length = 100, ending = '...') {
      if (str.length > length) {
        return str.substring(0, length - ending.length) + ending;
      }
      return str;
    },

    /**
     * Turns text into a URL slug: normalized, lower-cased, punctuation dropped
     * and spaces turned into single hyphens.
     *
     * @param {string} str - Text to convert
     * @returns {string} Slug
     */
    slugify(str) {
      return str.normalize("NFKD")
        .toLowerCase()
        .replace(/[^\w\s-]/g, '')
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .replace(/^-+|-+$/g, '');
    },

    /**
     * Returns the text content of markup, with the tags removed.
     *
     * @param {string} html - Markup to strip
     * @returns {string} Plain text
     */
    stripTags(html) {
      const div = document.createElement('div');
      div.innerHTML = html;
      return div.textContent || div.innerText || '';
    },

    /**
     * Formatters whose single argument is a pattern that may contain colons
     * itself ('HH:mm'): everything after the name is that one argument.
     */
    patternFormatters: ['date', 'datetime', 'time'],

    /**
     * Splits a formatter expression into its name and its arguments.
     *
     * Arguments follow the name, separated by colons: 'currency:THB:th-TH:2'.
     * A colon inside quotes belongs to the argument, and the quotes are
     * dropped: "default:'n/a: none'". The date formatters take one argument —
     * the pattern — so 'datetime:D MMM YYYY HH:mm' keeps its pattern whole,
     * quoted or not.
     *
     * @param {string} formatter - Formatter expression
     * @returns {{name: string, args: string[]}} Name and arguments
     */
    parseFormatter(formatter) {
      const text = String(formatter);
      const colon = text.indexOf(':');
      if (colon === -1) {
        return {name: text.trim(), args: []};
      }

      const name = text.slice(0, colon).trim();
      const rest = text.slice(colon + 1);
      const unquote = (arg) => {
        const trimmed = arg.trim();
        const quote = trimmed[0];
        return trimmed.length >= 2 && (quote === "'" || quote === '"') && trimmed[trimmed.length - 1] === quote
          ? trimmed.slice(1, -1)
          : arg;
      };

      if (this.patternFormatters.includes(name)) {
        return {name, args: [unquote(rest)]};
      }

      const args = [];
      let current = '';
      let quote = null;
      for (const ch of rest) {
        if (quote) {
          if (ch === quote) quote = null;
          current += ch;
        } else if (ch === "'" || ch === '"') {
          quote = ch;
          current += ch;
        } else if (ch === ':') {
          args.push(unquote(current));
          current = '';
        } else {
          current += ch;
        }
      }
      args.push(unquote(current));

      return {name, args};
    },

    /**
     * Runs a value through a chain of named formatters, each taking its
     * arguments after a colon, as in 'date:D MMM YYYY' (see parseFormatter()).
     *
     * A name is looked up in the context filters, then in the built-in
     * formatters, then in window.formatters; an unknown one is warned about and
     * the value passes through unchanged.
     *
     * @param {*} value - Value to format
     * @param {string[]} formatters - Formatter expressions in order
     * @param {Object} context - Context whose filters take priority
     * @returns {*} Formatted value
     */
    applyFormatters(value, formatters, context) {
      return formatters.reduce((val, formatter) => {
        const {name, args} = this.parseFormatter(formatter);

        // Skip empty formatter names (e.g., from "value | " or number literals)
        if (!name || name.trim() === '' || !isNaN(name)) {
          return val;
        }

        const format = context.filters?.[name]
          || this.builtinFormatters[name]
          || (typeof window !== 'undefined' && window.formatters ? window.formatters[name] : undefined);

        if (typeof format === 'function') {
          return format(val, ...args);
        }

        console.warn(`[Utils] Formatter "${name}" not found`);
        return val;
      }, value);
    },

    // The number formatters leave a value that is not a number as it is: a
    // missing value (null · undefined · '') stays empty instead of showing
    // 0.00 or NaN, the way data-format does in a table cell, so
    // `x | number:2 | default:'-'` and `x == null ? '-' : x | number:2` work
    builtinFormatters: {
      number: (value, decimals = 0) => {
        return isFormattableNumber(value) ? Utils.number.format(value, parseInt(decimals)) : value;
      },

      currency: (value, currency = null, locale = 'en-US', decimals = 2) => {
        return isFormattableNumber(value) ? Utils.number.currency(value, currency, locale, decimals) : value;
      },

      percent: (value, decimals = 0) => {
        return isFormattableNumber(value) ? Utils.number.percentage(value, decimals) : value;
      },

      // A byte count with its unit (2 KB · 1.5 MB), the same as data-format="bytes" of a table cell
      bytes: (value) => {
        return isFormattableNumber(value) ? Utils.number.fileSize(value) : value;
      },

      lowercase: value => String(value).toLowerCase(),
      uppercase: value => String(value).toUpperCase(),
      capitalize: value => {
        const str = String(value);
        return str.charAt(0).toUpperCase() + str.slice(1);
      },
      humanize: value => Utils.string.humanize(value),

      date: (value, format = 'D MMM YYYY') => {
        return Utils.date.format(value, format);
      },

      datetime: (value, format = 'D MMM YYYY HH:mm') => {
        return Utils.date.format(value, format);
      },

      time: (value, format = 'HH:mm') => {
        return Utils.date.format(value, format);
      },

      default: (value, defaultValue = '') => {
        return value == null ? defaultValue : value;
      }
    }
  },

  options: {
    /**
     * Normalizes any option source into a list of {value, text} entries, with
     * groups kept as {label, options}.
     *
     * Accepts an array of pairs, objects or scalars, a Map, a plain object, a
     * {success, data} response envelope, and the name of a global variable
     * holding any of those. A URL is rejected: it must be fetched first.
     *
     * @param {Array|Map|Object|string} source - Option source
     * @returns {Object[]|null} Normalized options, or null when unusable
     */
    normalizeSource(source) {
      if (!source) return null;

      if (typeof source === 'string') {
        if (/^(https?:\/\/|\/|api\/)|\//i.test(source)) return null;

        try {
          if (typeof window !== 'undefined' && window[source]) {
            source = window[source];
          } else {
            try {
              source = JSON.parse(source);
            } catch (e) {
              // Leave string as-is and let validation below handle it.
            }
          }
        } catch (e) {
          // Ignore and continue validation below.
        }
      }

      if (Array.isArray(source)) {
        return source.map(item => {
          if (Array.isArray(item) && item.length >= 2) {
            return {value: String(item[0]), text: String(item[1])};
          }

          if (item && typeof item === 'object') {
            if (item.options !== undefined) {
              return {
                ...item,
                label: String(item.label ?? item.text ?? item.name ?? ''),
                options: this.normalizeSource(item.options) || []
              };
            }

            const rawValue = item.value !== undefined ? item.value : (item.id ?? item.key ?? item.name ?? '');
            const rawText = item.text ?? item.label ?? item.name ?? rawValue;

            return {
              ...item,
              value: String(rawValue),
              text: String(rawText)
            };
          }

          const str = String(item);
          return {value: str, text: str};
        });
      }

      if (source instanceof Map) {
        const result = [];
        for (const [key, value] of source.entries()) {
          if (value && typeof value === 'object' && value.options !== undefined) {
            result.push({
              ...value,
              label: String(value.label ?? value.text ?? value.name ?? key),
              options: this.normalizeSource(value.options) || []
            });
            continue;
          }

          if (value && typeof value === 'object') {
            const rawValue = value.value !== undefined ? value.value : (value.id ?? value.key ?? key);
            const rawText = value.text ?? value.label ?? value.name ?? rawValue;
            result.push({
              ...value,
              value: String(rawValue),
              text: String(rawText)
            });
            continue;
          }

          result.push({value: String(key), text: String(value)});
        }
        return result;
      }

      if (typeof source === 'object' && source !== null) {
        if (Object.prototype.hasOwnProperty.call(source, 'success') && Object.prototype.hasOwnProperty.call(source, 'data')) {
          return this.normalizeSource(source.data);
        }

        return Object.entries(source).map(([key, value]) => {
          if (value && typeof value === 'object' && !Array.isArray(value)) {
            if (value.options !== undefined) {
              return {
                ...value,
                label: String(value.label ?? value.text ?? value.name ?? key),
                options: this.normalizeSource(value.options) || []
              };
            }

            const rawValue = value.value !== undefined ? value.value : (value.id ?? value.key ?? key);
            const rawText = value.text ?? value.label ?? value.name ?? rawValue;

            return {
              ...value,
              value: String(rawValue),
              text: String(rawText)
            };
          }

          return {
            value: String(key),
            text: String(value)
          };
        });
      }

      console.warn('[Utils.options] Invalid source format. Expected Array, Map, or Object.');
      return null;
    },

    /**
     * Flattens grouped options into a single list of entries.
     *
     * @param {Object[]} options - Options, possibly containing groups
     * @returns {Object[]} Entries with the groups unwrapped
     */
    flattenGroups(options) {
      if (!Array.isArray(options)) return [];

      return options.flatMap(item => {
        if (item && typeof item === 'object' && Array.isArray(item.options)) {
          return this.flattenGroups(item.options);
        }
        return [item];
      });
    }
  },

  number: {
    /**
     * Formats a number with thousands separators, in the locale of the browser.
     *
     * @param {number} num - Number to format
     * @param {number} [decimals=0] - Decimal places, fixed
     * @returns {string} Formatted number
     */
    format(num, decimals = 0) {
      return Number(num).toLocaleString(undefined, {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals
      });
    },

    /**
     * Format as currency
     * @param {number} amount - Amount to format
     * @param {string|null} currency - Currency code (e.g., 'THB', 'USD'). If null, no symbol shown.
     * @param {string} locale - Locale for formatting
     * @param {number} decimals - Decimal places
     * @returns {string} Formatted currency string
     * @example
     *   currency(1234.56)           // '1,234.56' (no symbol)
     *   currency(1234.56, 'THB')    // '1,234.56 บาท'
     *   currency(1234.56, 'USD')    // '1,234.56 USD'
     */
    currency(amount, currency = null, locale = 'en-US', decimals = 2) {
      const parsedDecimals = parseInt(decimals, 10);
      const fractionDigits = Number.isNaN(parsedDecimals) ? 2 : Math.max(0, parsedDecimals);
      const formatter = new Intl.NumberFormat(locale || 'en-US', {
        minimumFractionDigits: fractionDigits,
        maximumFractionDigits: fractionDigits
      });
      return formatter.format(amount) + (currency ? ' ' + Now.translate(currency) : '');
    },

    /**
     * Formats a ratio as a percentage, so 0.25 becomes '25%'.
     *
     * @param {number} num - Ratio, where 1 is 100%
     * @param {number} [decimals=0] - Decimal places
     * @returns {string} Formatted percentage
     */
    percentage(num, decimals = 0) {
      return (num * 100).toFixed(decimals) + '%';
    },

    /**
     * Formats a byte count with the largest unit that fits, keeping two decimal
     * places.
     *
     * @param {number} bytes - Size in bytes
     * @returns {string} Size with its unit
     */
    fileSize(bytes) {
      const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
      const value = Number(bytes);
      if (!Number.isFinite(value) || value <= 0) return '0 Byte';

      const i = Math.min(
        Math.floor(Math.log(value) / Math.log(1024)),
        sizes.length - 1
      );

      return this.round(value / Math.pow(1024, i), 2) + ' ' + sizes[i];
    },

    /**
     * Rounds to a number of decimal places.
     *
     * @param {number} val - Value to round
     * @param {number} [precision=2] - Decimal places
     * @returns {number} Rounded value
     */
    round(val, precision = 2) {
      const factor = Math.pow(10, precision);
      return Math.round(val * factor) / factor;
    },

    /**
     * Rounds up to a number of decimal places.
     *
     * @param {number} val - Value to round
     * @param {number} [precision=2] - Decimal places
     * @returns {number} Rounded value
     */
    ceil(val, precision = 2) {
      const factor = Math.pow(10, precision);
      return Math.ceil(val * factor) / factor;
    },

    /**
     * Rounds down to a number of decimal places.
     *
     * @param {number} val - Value to round
     * @param {number} [precision=2] - Decimal places
     * @returns {number} Rounded value
     */
    floor(val, precision = 2) {
      const factor = Math.pow(10, precision);
      return Math.floor(val * factor) / factor;
    },

    /**
     * Drops the digits past a number of decimal places, without rounding.
     *
     * @param {number} val - Value to truncate
     * @param {number} [precision=2] - Decimal places to keep
     * @returns {number} Truncated value
     */
    truncate(val, precision = 2) {
      const factor = Math.pow(10, precision);
      return Math.trunc(val * factor) / factor;
    }
  },

  date: {
    /**
     * Format date with standard tokens and locale-based year system
     *
     * Standard Format Tokens (ISO 8601 / Unicode LDML compatible):
     *
     * Year:
     *   YYYY = 4-digit year (2025 CE or 2568 BE based on locale)
     *   YY = 2-digit year (25 or 68 based on locale)
     *
     * Month:
     *   MMMM = Full month name localized (January/มกราคม)
     *   MMM = Short month name localized (Jan/ม.ค.)
     *   MM = Month with zero (01-12)
     *   M = Month without zero (1-12)
     *
     * Day:
     *   DD = Day with zero (01-31)
     *   D = Day without zero (1-31)
     *
     * Time:
     *   HH = Hours 24h with zero (00-23)
     *   H = Hours 24h without zero (0-23)
     *   hh = Hours 12h with zero (01-12)
     *   h = Hours 12h without zero (1-12)
     *   mm = Minutes with zero (00-59)
     *   ss = Seconds with zero (00-59)
     *   A = AM/PM uppercase
     *   a = am/pm lowercase
     *
     * Locale Behavior:
     *   'th' or 'th-TH' = Buddhist Era (BE): YYYY shows 2568
     *   'th-CE' = Force Christian Era: YYYY shows 2025
     *   'en' or others = Christian Era (CE): YYYY shows 2025
     *
     * Examples:
     *   Utils.date.format(date, 'D MMMM YYYY') // Auto locale
     *   Utils.date.format(date, 'D MMMM YYYY', 'th') // "15 พฤษภาคม 2568"
     *   Utils.date.format(date, 'D MMMM YYYY', 'th-CE') // "15 พฤษภาคม 2025"
     *   Utils.date.format(date, 'D MMMM YYYY', 'en') // "15 May 2025"
     *
     * @param {Date|string} date - Date to format
     * @param {string} format - Format pattern (standard tokens)
     * @param {string} locale - Locale code (auto-detect if not provided)
     *   - 'th' or 'th-TH' = Thai with BE year
     *   - 'th-CE' = Thai with CE year
     *   - 'en' or others = English with CE year
     * @returns {string} Formatted date string
     *
     * Normalise a value before handing it to `new Date()`.
     *
     * REST APIs commonly send unix timestamps in **seconds** while `new Date()`
     * expects **milliseconds**, so a raw `1801573993` renders as 22 Jan 1970
     * instead of 2027. The date is wrong but still a valid date, so nothing
     * throws and nothing warns — it only shows up when a human reads the screen.
     *
     * Anything below 1e11 is treated as seconds. That threshold is 1973 in
     * milliseconds and the year 5138 in seconds, so real millisecond timestamps
     * from this era are never misread.
     *
     * @param {*} value
     * @returns {*} value ready for `new Date()`
     */
    /**
     * Normalizes a date input for the Date constructor, converting a Unix
     * timestamp in seconds to milliseconds.
     *
     * A number small enough to be seconds is multiplied by 1000; anything else
     * passes through untouched.
     *
     * @param {number|string|Date} value - Value to normalize
     * @returns {number|string|Date} Value the Date constructor can take
     */
    toDateInput(value) {
      const n = typeof value === 'string' && value.trim() !== '' && !isNaN(Number(value))
        ? Number(value)
        : value;

      return (typeof n === 'number' && isFinite(n) && Math.abs(n) < 1e11) ? n * 1000 : n;
    },

    /**
     * Formats a date with a pattern of YYYY, MM, DD, HH, mm, ss, the month name
     * tokens (MMMM · MMM) and the day name tokens (dddd · ddd).
     *
     * The locale comes from I18nManager when none is given. Empty and
     * unparseable values return an empty string rather than 'Invalid Date'.
     *
     * @param {Date|number|string} date - Date to format
     * @param {string} [format='YYYY-MM-DD'] - Pattern
     * @param {string} [locale=null] - Locale override
     * @returns {string} Formatted date, empty when there is no usable date
     */
    format(date, format = 'YYYY-MM-DD', locale = null) {
      // Treat null/undefined/empty-string as no value -> return empty string
      if (date == null || date === '') return '';

      const d = new Date(Utils.date.toDateInput(date));
      if (isNaN(d.getTime())) return '';

      // Auto-detect locale if not provided
      if (!locale) {
        // Try I18nManager first (primary source)
        const i18n = window.Now?.getManager?.('i18n') || window.I18nManager;
        if (i18n?.getCurrentLocale) {
          locale = i18n.getCurrentLocale();
        } else if (window.LanguageManager?.getCurrentLanguage) {
          locale = window.LanguageManager.getCurrentLanguage();
        }

        if (!locale) {
          locale = document.documentElement?.getAttribute('lang') || 'en';
        }
      }

      // Determine if we should use BE (Buddhist Era) or CE (Christian Era)
      const useBE = locale.startsWith('th') && !locale.includes('-CE');
      const baseLocale = locale.split('-')[0]; // Extract base locale (th, en, etc.)

      const year = d.getFullYear();
      const displayYear = useBE ? year + 543 : year;
      const month = d.getMonth();

      // Month names
      const monthNamesTh = [
        'มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน',
        'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'
      ];
      const monthNamesThShort = [
        'ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.',
        'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'
      ];
      const monthNamesEn = [
        'January', 'February', 'March', 'April', 'May', 'June',
        'July', 'August', 'September', 'October', 'November', 'December'
      ];
      const monthNamesEnShort = [
        'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
        'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'
      ];

      const monthFull = baseLocale === 'th' ? monthNamesTh[month] : monthNamesEn[month];
      const monthShort = baseLocale === 'th' ? monthNamesThShort[month] : monthNamesEnShort[month];

      // Day names (dddd · ddd), Sunday first as getDay() counts
      const dayNames = baseLocale === 'th'
        ? ['อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์']
        : ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
      const dayNamesShort = baseLocale === 'th'
        ? ['อา.', 'จ.', 'อ.', 'พ.', 'พฤ.', 'ศ.', 'ส.']
        : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

      const tokens = {
        // Year (locale-based: BE for Thai, CE for others)
        'YYYY': displayYear,
        'YY': String(displayYear).slice(-2),
        // Month
        'MMMM': monthFull,
        'MMM': monthShort,
        'MM': String(month + 1).padStart(2, '0'),
        'M': month + 1,
        // Day
        'dddd': dayNames[d.getDay()],
        'ddd': dayNamesShort[d.getDay()],
        'DD': String(d.getDate()).padStart(2, '0'),
        'D': d.getDate(),
        // Time
        'HH': String(d.getHours()).padStart(2, '0'),
        'H': d.getHours(),
        'hh': String(d.getHours() % 12 || 12).padStart(2, '0'),
        'h': d.getHours() % 12 || 12,
        'mm': String(d.getMinutes()).padStart(2, '0'),
        'ss': String(d.getSeconds()).padStart(2, '0'),
        'A': d.getHours() < 12 ? 'AM' : 'PM',
        'a': d.getHours() < 12 ? 'am' : 'pm'
      };

      // One pass: a replaced name is never scanned again ("Monday" keeps its "M")
      return format.replace(/YYYY|YY|MMMM|MMM|MM|M|dddd|ddd|DD|D|HH|H|hh|h|mm|ss|A|a/g, match => tokens[match]);
    },

    /**
     * Parse a variety of date/time inputs into a local Date object.
     * Supports: Date, numeric timestamps (seconds or ms), ISO-like strings,
     * YYYY/MM/DD, DD/MM/YYYY, and common datetime formats.
     * @param {Date|string|number} input
     * @param {string} type Optional hint: 'date', 'datetime-local', 'time'
     * @returns {Date|null}
     */
    parse(input, type = 'date') {
      if (input == null || input === '') return null;
      if (input instanceof Date) return isNaN(input.getTime()) ? null : input;

      let v = String(input).trim();
      if (!v) return null;

      // numeric timestamp (seconds or ms)
      if (/^\d+$/.test(v)) {
        if (v.length === 10) v = String(parseInt(v, 10) * 1000);
        const d = new Date(Number(v));
        return Number.isNaN(d.getTime()) ? null : d;
      }

      // ISO-like YYYY-MM-DD[ T]HH:MM[:SS]
      const iso = v.match(/^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{2}):(\d{2})(?::(\d{2}))?)?/);
      if (iso) {
        const y = parseInt(iso[1], 10);
        const mo = parseInt(iso[2], 10) - 1;
        const d = parseInt(iso[3], 10);
        const hh = parseInt(iso[4] || '0', 10);
        const mm = parseInt(iso[5] || '0', 10);
        const ss = parseInt(iso[6] || '0', 10);
        return new Date(y, mo, d, hh, mm, ss, 0);
      }

      // Slash or dash ambiguous formats: try YYYY/MM/DD, DD/MM/YYYY
      const slash = v.match(/^(\d{1,4})[\/\-](\d{1,2})[\/\-](\d{1,4})(?:[\sT](\d{2}):(\d{2})(?::(\d{2}))?)?/);
      if (slash) {
        const a = slash[1], b = slash[2], c = slash[3];
        const hh = parseInt(slash[4] || '0', 10);
        const mm = parseInt(slash[5] || '0', 10);
        const ss = parseInt(slash[6] || '0', 10);
        let y, mo, day;
        if (a.length === 4) {
          y = parseInt(a, 10); mo = parseInt(b, 10) - 1; day = parseInt(c, 10);
        } else if (c.length === 4) {
          y = parseInt(c, 10); mo = parseInt(b, 10) - 1; day = parseInt(a, 10);
        } else {
          const d = new Date(v);
          return Number.isNaN(d.getTime()) ? null : d;
        }
        return new Date(y, mo, day, hh, mm, ss, 0);
      }

      // fallback
      const fallback = new Date(v);
      return Number.isNaN(fallback.getTime()) ? null : fallback;
    },

    /**
     * Builds a Date from a Unix timestamp in seconds.
     *
     * @param {number} timestamp - Seconds since the epoch
     * @returns {Date} The date
     */
    fromTimestamp(timestamp) {
      return new Date(timestamp * 1000);
    },

    /**
     * Converts a date to a Unix timestamp in seconds.
     *
     * @param {Date|number|string} date - Date to convert
     * @returns {number} Seconds since the epoch
     */
    toTimestamp(date) {
      return Math.floor(new Date(date).getTime() / 1000);
    },

    /**
     * Returns a new date shifted by an amount of a unit.
     *
     * @param {Date|number|string} date - Starting date
     * @param {number} amount - Amount to add; negative subtracts
     * @param {string} unit - 'years', 'months', 'days', 'hours', 'minutes' or 'seconds'
     * @returns {Date} The shifted date
     */
    add(date, amount, unit) {
      const d = new Date(date);
      switch (unit) {
        case 'years': d.setFullYear(d.getFullYear() + amount); break;
        case 'months': d.setMonth(d.getMonth() + amount); break;
        case 'days': d.setDate(d.getDate() + amount); break;
        case 'hours': d.setHours(d.getHours() + amount); break;
        case 'minutes': d.setMinutes(d.getMinutes() + amount); break;
        case 'seconds': d.setSeconds(d.getSeconds() + amount); break;
      }
      return d;
    },

    /**
     * Returns a new date shifted by a number of days.
     *
     * @param {Date|number|string} date - Starting date
     * @param {number} days - Days to add; negative subtracts
     * @returns {Date} The shifted date
     */
    moveDate(date, days) {
      const d = new Date(date);
      d.setDate(d.getDate() + days);
      return d;
    },

    /**
     * Returns a new date shifted by a number of months.
     *
     * @param {Date|number|string} date - Starting date
     * @param {number} months - Months to add; negative subtracts
     * @returns {Date} The shifted date
     */
    moveMonth(date, months) {
      const d = new Date(date);
      d.setMonth(d.getMonth() + months);
      return d;
    },

    /**
     * Returns a new date shifted by a number of years.
     *
     * @param {Date|number|string} date - Starting date
     * @param {number} years - Years to add; negative subtracts
     * @returns {Date} The shifted date
     */
    moveYear(date, years) {
      const d = new Date(date);
      d.setFullYear(d.getFullYear() + years);
      return d;
    },

    /**
     * Converts a HH:mm string to minutes since midnight.
     *
     * @param {string} timeStr - Time as HH:mm
     * @returns {number} Minutes since midnight
     */
    timeToMinute(timeStr) {
      const [hours, minutes] = timeStr.split(':').map(Number);
      return hours * 60 + minutes;
    },

    /**
     * Converts a HH:mm:ss string to seconds since midnight, treating a missing
     * seconds part as zero.
     *
     * @param {string} timeStr - Time as HH:mm or HH:mm:ss
     * @returns {number} Seconds since midnight
     */
    timeToSecond(timeStr) {
      const [hours, minutes, seconds] = timeStr.split(':').map(Number);
      return hours * 3600 + minutes * 60 + (seconds || 0);
    },

    /**
     * Reports whether a year is a leap year.
     *
     * @param {number} year - Year to test
     * @returns {boolean} True for a leap year
     */
    isLeapYear(year) {
      return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
    },

    /**
     * Returns the number of days in a month.
     *
     * @param {number} year - Year
     * @param {number} month - Month, 1 for January
     * @returns {number} Days in that month
     */
    daysInMonth(year, month) {
      return new Date(year, month, 0).getDate();
    },

    /**
     * Returns the distance from the second date to the first, in days, months
     * and years.
     *
     * @param {Date|number|string} date1 - Later date
     * @param {Date|number|string} date2 - Earlier date
     * @returns {Object} {days, months, years}, negative when date1 comes first
     */
    compare(date1, date2) {
      const d1 = new Date(date1);
      const d2 = new Date(date2);
      const diffTime = d1.getTime() - d2.getTime();
      const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
      const diffMonths = d1.getMonth() - d2.getMonth() + (12 * (d1.getFullYear() - d2.getFullYear()));
      const diffYears = d1.getFullYear() - d2.getFullYear();
      return {days: diffDays, months: diffMonths, years: diffYears};
    },

    /**
     * Get locale with auto-detection from I18nManager
     * @param {string|null} locale - Locale override or null for auto-detect
     * @returns {string} Resolved locale code
     */
    getLocale(locale = null) {
      if (locale) return locale;
      const i18n = window.Now?.getManager?.('i18n') || window.I18nManager;
      if (i18n?.getCurrentLocale) {
        return i18n.getCurrentLocale();
      }
      return document.documentElement?.getAttribute('lang') || 'en';
    },

    /**
     * Get localized month names (full form)
     * @param {string|null} locale - Locale code or null for auto-detect
     * @returns {string[]} Array of 12 month names
     */
    getMonthNames(locale = null) {
      const loc = this.getLocale(locale);
      const baseLocale = loc.split('-')[0];

      if (baseLocale === 'th') {
        return [
          'มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน',
          'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'
        ];
      }
      return [
        'January', 'February', 'March', 'April', 'May', 'June',
        'July', 'August', 'September', 'October', 'November', 'December'
      ];
    },

    /**
     * Get localized month names (short form)
     * @param {string|null} locale - Locale code or null for auto-detect
     * @returns {string[]} Array of 12 short month names
     */
    getMonthNamesShort(locale = null) {
      const loc = this.getLocale(locale);
      const baseLocale = loc.split('-')[0];

      if (baseLocale === 'th') {
        return [
          'ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.',
          'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'
        ];
      }
      return [
        'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
        'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'
      ];
    },

    /**
     * Get localized day names (short form)
     * @param {string|null} locale - Locale code or null for auto-detect
     * @returns {string[]} Array of 7 day names starting from Sunday
     */
    getDayNames(locale = null) {
      const loc = this.getLocale(locale);
      const baseLocale = loc.split('-')[0];

      if (baseLocale === 'th') {
        return ['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'];
      }
      return ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    },

    /**
     * Get localized day names (narrow/single character)
     * @param {string|null} locale - Locale code or null for auto-detect
     * @returns {string[]} Array of 7 narrow day names starting from Sunday
     */
    getDayNamesNarrow(locale = null) {
      const loc = this.getLocale(locale);
      const baseLocale = loc.split('-')[0];

      if (baseLocale === 'th') {
        return ['อ', 'จ', 'อ', 'พ', 'พ', 'ศ', 'ส'];
      }
      return ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
    }
  },

  object: {
    /**
     * Reports whether a key must never be written by a merge, clone or set
     * operation, which is what keeps them free of prototype pollution.
     *
     * @param {string} key - Key about to be written
     * @returns {boolean} True when the key is unsafe
     */
    isUnsafeKey(key) {
      return key === '__proto__' || key === 'constructor' || key === 'prototype';
    },

    /**
     * Clones a value deeply, skipping inherited properties and the keys
     * isUnsafeKey() rejects. Dates are copied as Dates.
     *
     * @param {*} obj - Value to clone
     * @returns {*} The clone
     */
    deepClone(obj) {
      if (obj === null || typeof obj !== 'object') return obj;
      if (obj instanceof Date) return new Date(obj.getTime());
      if (Array.isArray(obj)) return obj.map(item => this.deepClone(item));
      const clone = {};
      for (let key in obj) {
        if (this.isUnsafeKey(key) || !Object.prototype.hasOwnProperty.call(obj, key)) continue;
        clone[key] = this.deepClone(obj[key]);
      }
      return clone;
    },

    /**
     * Merges each source into the target recursively, skipping the keys
     * isUnsafeKey() rejects.
     *
     * @param {Object} target - Object to merge into; mutated
     * @param {...Object} sources - Objects to merge from, in order
     * @returns {Object} The merged target
     */
    merge(target, ...sources) {
      if (!sources.length) return target;
      const source = sources.shift();

      if (this.isObject(target) && this.isObject(source)) {
        for (const key in source) {
          if (this.isUnsafeKey(key) || !Object.prototype.hasOwnProperty.call(source, key)) continue;
          if (this.isObject(source[key])) {
            if (!target[key]) Object.assign(target, {[key]: {}});
            this.merge(target[key], source[key]);
          } else {
            Object.assign(target, {[key]: source[key]});
          }
        }
      }

      return this.merge(target, ...sources);
    },

    /**
     * Reports whether a value is a plain object rather than an array or null.
     *
     * @param {*} item - Value to test
     * @returns {boolean} True for an object
     */
    isObject(item) {
      return item && typeof item === 'object' && !Array.isArray(item);
    },

    /**
     * Reads a nested value by path, accepting both dot and bracket notation.
     *
     * @param {Object} obj - Object to read from
     * @param {string} path - Path such as 'user.roles[0]'
     * @param {*} [defaultValue=null] - Value when the path resolves to nothing
     * @returns {*} The value, or the default
     */
    get(obj, path, defaultValue = null) {
      if (!obj || !path) {
        console.warn('[Utils.object.get] Invalid parameters');
        return defaultValue;
      }
      const travel = regexp =>
        String.prototype.split
          .call(path, regexp)
          .filter(Boolean)
          .reduce((res, key) => (res !== null && res !== undefined ? res[key] : res), obj);
      const result = travel(/[,[\]]+?/) || travel(/[,[\].]+?/);
      return result === undefined || result === obj ? defaultValue : result;
    }
  },

  array: {
    /**
     * Splits an array into runs of a fixed size, the last one shorter when the
     * length does not divide evenly.
     *
     * @param {Array} arr - Array to split
     * @param {number} size - Items per chunk
     * @returns {Array[]} The chunks
     * @throws {Error} When the input is not an array or the size is not positive
     */
    chunk(arr, size) {
      if (!Array.isArray(arr)) throw new Error('[Utils.array.chunk] Input must be an array');
      if (typeof size !== 'number' || size <= 0) throw new Error('[Utils.array.chunk] Size must be a positive number');
      return Array.from(
        {length: Math.ceil(arr.length / size)},
        (v, i) => arr.slice(i * size, i * size + size)
      );
    },

    /**
     * Removes duplicates, comparing whole items or the value at a key.
     *
     * @param {Array} arr - Array to deduplicate
     * @param {string} [key=null] - Property to compare instead of the item
     * @returns {Array} Array without duplicates
     * @throws {Error} When the input is not an array
     */
    unique(arr, key = null) {
      if (!Array.isArray(arr)) throw new Error('[Utils.array.unique] Input must be an array');
      if (!key) return [...new Set(arr)];
      const seen = new Set();
      return arr.filter(item => {
        const k = key ? item[key] : item;
        return seen.has(k) ? false : seen.add(k);
      });
    },

    /**
     * Returns a shuffled copy, leaving the original alone.
     *
     * @param {Array} arr - Array to shuffle
     * @returns {Array} Shuffled copy
     * @throws {Error} When the input is not an array
     */
    shuffle(arr) {
      if (!Array.isArray(arr)) throw new Error('[Utils.array.shuffle] Input must be an array');
      const result = [...arr];
      for (let i = result.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [result[i], result[j]] = [result[j], result[i]];
      }
      return result;
    },

    /**
     * Groups items by the value at a key.
     *
     * @param {Object[]} arr - Items to group
     * @param {string} key - Property to group by
     * @returns {Object} Items keyed by that value
     */
    groupBy(arr, key) {
      return arr.reduce((grouped, item) => ({
        ...grouped,
        [item[key]]: [...(grouped[item[key]] || []), item]
      }), {});
    },

    /**
     * Flattens nested arrays to a depth.
     *
     * @param {Array} arr - Array to flatten
     * @param {number} [depth=1] - Levels to flatten
     * @returns {Array} Flattened array
     * @throws {Error} When the input is not an array
     */
    flatten(arr, depth = 1) {
      if (!Array.isArray(arr)) throw new Error('[Utils.array.flatten] Input must be an array');
      return arr.reduce((flat, item) =>
        flat.concat(depth > 0 && Array.isArray(item) ? this.flatten(item, depth - 1) : item), []);
    },

    /**
     * Finds the first item whose key holds a value.
     *
     * @param {Object[]} arr - Items to search
     * @param {string} key - Property to compare
     * @param {*} value - Value to look for
     * @returns {Object|undefined} The item, or undefined
     * @throws {Error} When the input is not an array
     */
    findBy(arr, key, value) {
      if (!Array.isArray(arr)) throw new Error('[Utils.array.findBy] Input must be an array');
      return arr.find(item => item[key] === value);
    }
  },

  validate: {
    /**
     * Reports whether text looks like an email address.
     *
     * @param {string} email - Text to check
     * @returns {boolean} True when the shape is right
     */
    email(email) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    },

    /**
     * Reports whether text parses as a URL.
     *
     * @param {string} url - Text to check
     * @returns {boolean} True when it parses
     */
    url(url) {
      try {
        new URL(url);
        return true;
      } catch {
        return false;
      }
    },

    /**
     * Reports whether text looks like a phone number: 9 to 15 digits, with the
     * usual separators and an optional leading plus.
     *
     * @param {string} phone - Text to check
     * @returns {boolean} True when the shape is right
     */
    phone(phone) {
      if (typeof phone !== 'string') return false;
      const digitsOnly = phone.replace(/[^\d]/g, '');
      if (digitsOnly.length < 9 || digitsOnly.length > 15) return false;
      return /^\+?[\d\s().-]{10,}$/.test(phone);
    },

    /**
     * Scores a password on length, mixed case, digits and symbols.
     *
     * @param {string} password - Password to score
     * @returns {Object} {score, label, isStrong}, with a score of 0 to 4
     */
    password(password) {
      const strength = {
        0: "Too weak",
        1: "Weak",
        2: "Medium",
        3: "Strong"
      };

      let score = 0;
      if (password.length >= 8) score++;
      if (/[A-Z]/.test(password) && /[a-z]/.test(password)) score++;
      if (/[0-9]/.test(password)) score++;
      if (/[^A-Za-z0-9]/.test(password)) score++;

      return {
        score,
        label: strength[score],
        isStrong: score >= 3
      };
    }
  },

  dom: {
    _resourcePromises: new Map(),

    /**
     * Load an external script (.js) or stylesheet (.css) once.
     * Repeat calls with the same url reuse the same promise instead of
     * inserting the tag again.
     * @param {string} url
     * @returns {Promise<void>}
     */
    loadResource(url) {
      if (this._resourcePromises.has(url)) {
        return this._resourcePromises.get(url);
      }

      const ext = url.split('?')[0].split('.').pop().toLowerCase();
      const selector = ext === 'css' ? `link[href="${url}"]` : `script[src="${url}"]`;

      if (document.querySelector(selector)) {
        const loaded = Promise.resolve();
        this._resourcePromises.set(url, loaded);
        return loaded;
      }

      const promise = new Promise((resolve, reject) => {
        let element;
        if (ext === 'css') {
          element = document.createElement('link');
          element.rel = 'stylesheet';
          element.href = url;
        } else {
          element = document.createElement('script');
          element.src = url;
          element.async = true;
        }
        element.onload = () => resolve();
        element.onerror = () => {
          element.remove();
          this._resourcePromises.delete(url);
          reject(new Error(`Failed to load: ${url}`));
        };
        document.head.appendChild(element);
      });

      this._resourcePromises.set(url, promise);
      return promise;
    },

    /**
     * Load multiple scripts/stylesheets in parallel, skipping any already loaded.
     * @param {string[]} urls
     * @returns {Promise<void[]>}
     */
    loadResources(urls) {
      return Promise.all(urls.map(url => this.loadResource(url)));
    },

    /**
     * Builds an element with attributes and children in one call.
     *
     * className and dataset are handled as properties; everything else is set
     * as an attribute. String children become text nodes.
     *
     * @param {string} tag - Tag name
     * @param {Object} [attributes={}] - Attributes, plus className and dataset
     * @param {Array<Node|string>} [children=[]] - Children to append
     * @returns {HTMLElement} The new element
     */
    create(tag, attributes = {}, children = []) {
      const element = document.createElement(tag);
      Object.entries(attributes).forEach(([key, value]) => {
        if (key === 'className') {
          element.className = value;
        } else if (key === 'dataset') {
          Object.entries(value).forEach(([dataKey, dataValue]) => {
            element.dataset[dataKey] = dataValue;
          });
        } else {
          element.setAttribute(key, value);
        }
      });
      children.forEach(child => {
        if (typeof child === 'string') {
          element.appendChild(document.createTextNode(child));
        } else {
          element.appendChild(child);
        }
      });
      return element;
    },

    /**
     * Toggles one or more classes on an element.
     *
     * @param {HTMLElement} element - Element to change
     * @param {...string} classNames - Classes to toggle
     * @returns {void}
     */
    toggleClass(element, ...classNames) {
      classNames.forEach(className =>
        element.classList.toggle(className)
      );
    },

    /**
     * Returns the closest ancestor matching a selector, the element itself
     * included.
     *
     * @param {Element} element - Element to start from
     * @param {string} selector - CSS selector
     * @returns {Element|null} The match, or null
     */
    closest(element, selector) {
      return element.closest(selector);
    },

    /**
     * Reports whether an element takes up space on the page.
     *
     * @param {HTMLElement} element - Element to test
     * @returns {boolean} True when it is rendered
     */
    isVisible(element) {
      return !!(element.offsetWidth || element.offsetHeight || element.getClientRects().length);
    },

    /**
     * Copy text to clipboard
     * @param {string} text - Text to copy
     * @returns {Promise<boolean>} - Returns true if successful, false otherwise
     */
    async copyToClipboard(text) {
      if (typeof text !== 'string') {
        console.error('[Utils.dom.copyToClipboard] Text must be a string');
        return false;
      }

      // Modern Clipboard API (preferred method)
      if (navigator.clipboard && window.isSecureContext) {
        try {
          await navigator.clipboard.writeText(text);
          NotificationManager.success('Copied to clipboard');
          return true;
        } catch (error) {
          console.warn('[Utils.dom.copyToClipboard] Clipboard API failed, trying fallback:', error);
        }
      }

      // Fallback method for older browsers or non-secure contexts
      try {
        const textArea = document.createElement('textarea');
        textArea.value = text;
        textArea.style.position = 'fixed';
        textArea.style.left = '-999999px';
        textArea.style.top = '-999999px';
        textArea.setAttribute('aria-hidden', 'true');
        document.body.appendChild(textArea);

        textArea.focus();
        textArea.select();

        const successful = document.execCommand('copy');
        document.body.removeChild(textArea);

        if (successful) {
          NotificationManager.success('Copied to clipboard');
          return true;
        } else {
          console.error('[Utils.dom.copyToClipboard] Fallback method failed');
          return false;
        }
      } catch (error) {
        console.error('[Utils.dom.copyToClipboard] Failed to copy text:', error);
        return false;
      }
    }
  },

  browser: {
    /**
     * Identifies the browser from the user agent.
     *
     * @returns {Object} {name, version}
     */
    info() {
      const ua = navigator.userAgent;
      let tem;
      let M = ua.match(/(opera|chrome|safari|firefox|msie|trident(?=\/))\/?\s*(\d+)/i) || [];

      if (/trident/i.test(M[1])) {
        tem = /\brv[ :]+(\d+)/g.exec(ua) || [];
        return {name: 'IE', version: tem[1] || ''};
      }

      if (M[1] === 'Chrome') {
        tem = ua.match(/\bOPR|Edge\/(\d+)/);
        if (tem != null) {
          return {name: 'Opera', version: tem[1]};
        }
      }

      M = M[2] ? [M[1], M[2]] : [navigator.appName, navigator.appVersion, '-?'];
      if ((tem = ua.match(/version\/(\d+)/i)) != null) {
        M.splice(1, 1, tem[1]);
      }

      return {
        name: M[0],
        version: M[1]
      };
    },

    /**
     * Reports whether the user agent names a mobile device.
     *
     * @returns {boolean} True on mobile
     */
    isMobile() {
      return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    },

    /**
     * Reports the orientation of the viewport.
     *
     * @returns {string} 'portrait' or 'landscape'
     */
    orientation() {
      return window.innerHeight > window.innerWidth ? 'portrait' : 'landscape';
    }
  },

  session: {
    /**
     * Stores a value in session storage, optionally with a lifetime.
     *
     * @param {string} key - Storage key
     * @param {*} value - Value to store; JSON-encoded
     * @param {number} [ttl=null] - Lifetime in seconds
     * @returns {void}
     */
    set(key, value, ttl = null) {
      const item = {
        value: value,
        timestamp: new Date().getTime()
      };

      if (ttl) {
        item.expires = item.timestamp + (ttl * 1000);
      }

      try {
        sessionStorage.setItem(key, JSON.stringify(item));
      } catch (error) {
        console.error(`[Utils.session.set] Error setting key ${key}:`, error);
      }
    },

    /**
     * Reads a value from session storage, dropping it when its lifetime has
     * passed.
     *
     * @param {string} key - Storage key
     * @param {*} [defaultValue=null] - Value when the key is missing or expired
     * @returns {*} Stored value, or the default
     */
    get(key, defaultValue = null) {
      try {
        const item = sessionStorage.getItem(key);
        if (!item) return defaultValue;

        const parsed = JSON.parse(item);

        if (parsed.expires && new Date().getTime() > parsed.expires) {
          this.remove(key);
          return defaultValue;
        }

        return parsed.value;
      } catch (error) {
        console.error(`[Utils.session.get] Error getting key ${key}:`, error);
        return defaultValue;
      }
    },

    /**
     * Removes a key from session storage.
     *
     * @param {string} key - Storage key
     * @returns {void}
     */
    remove(key) {
      try {
        sessionStorage.removeItem(key);
      } catch (error) {
        console.error(`[Utils.session.remove] Error removing key ${key}:`, error);
      }
    },

    /**
     * Empties session storage.
     *
     * @returns {void}
     */
    clear() {
      try {
        sessionStorage.clear();
      } catch (error) {
        console.error('[Utils.session.clear] Error clearing session:', error);
      }
    },

    /**
     * Reports whether a key exists in session storage, without checking whether
     * it has expired.
     *
     * @param {string} key - Storage key
     * @returns {boolean} True when the key is present
     */
    has(key) {
      return sessionStorage.getItem(key) !== null;
    },

    /**
     * Returns how many keys session storage holds.
     *
     * @returns {number} Number of keys
     */
    size() {
      return sessionStorage.length;
    },

    /**
     * Lists the keys in session storage.
     *
     * @returns {string[]} The keys
     */
    keys() {
      return Object.keys(sessionStorage);
    }
  },

  /**
   * Generates a UUID, from crypto.randomUUID() where available and from a
   * random fallback otherwise.
   *
   * @returns {string} UUID
   */
  generateUUID() {
    if (crypto && crypto.randomUUID) {
      return crypto.randomUUID();
    } else {
      return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        const r = (Math.random() * 16) | 0;
        const v = c === 'x' ? r : (r & 0x3) | 0x8;
        return v.toString(16);
      });
    }
  },

  function: {
    /**
     * Wraps a function so it runs only after the calls stop for the wait
     * period.
     *
     * @param {Function} func - Function to defer
     * @param {number} [wait=300] - Quiet period in milliseconds
     * @returns {Function} The debounced function
     */
    debounce(func, wait = 300) {
      let timeout;
      return function executedFunction(...args) {
        const later = () => {
          clearTimeout(timeout);
          func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
      };
    },

    /**
     * Wraps a function so it runs at most once per interval, on the leading
     * edge.
     *
     * @param {Function} func - Function to rate-limit
     * @param {number} [limit=300] - Interval in milliseconds
     * @returns {Function} The throttled function
     */
    throttle(func, limit = 300) {
      let inThrottle;
      return function executedFunction(...args) {
        if (!inThrottle) {
          func(...args);
          inThrottle = true;
          setTimeout(() => inThrottle = false, limit);
        }
      };
    },

    /**
     * Debounces an async function. Only the last call of a burst runs, and the
     * promise of every call in that burst settles with its result (or its error).
     *
     * @param {Function} func - Async function to defer
     * @param {number} [wait=300] - Quiet period in milliseconds
     * @returns {Function} The debounced function, returning a promise
     */
    debounceAsync(func, wait = 300) {
      let timeout;
      let waiting = [];
      return function executedFunction(...args) {
        return new Promise((resolve, reject) => {
          // Earlier calls in the burst used to be dropped with their promise
          // still pending, so anything awaiting them waited forever
          waiting.push({resolve, reject});
          clearTimeout(timeout);
          timeout = setTimeout(async () => {
            const callers = waiting;
            waiting = [];
            try {
              const result = await func.apply(this, args);
              callers.forEach(caller => caller.resolve(result));
            } catch (error) {
              callers.forEach(caller => caller.reject(error));
            }
          }, wait);
        });
      };
    }
  },

  cookie: {
    /**
     * Writes a cookie, secure and SameSite=Strict by default.
     *
     * @param {string} name - Cookie name
     * @param {string} value - Value to store
     * @param {Object} [options={}] - Cookie options
     * @param {number} [options.days=7] - Lifetime in days; 0 for a session cookie
     * @param {string} [options.path='/'] - Path
     * @param {string} [options.domain=''] - Domain
     * @param {boolean} [options.secure=true] - Send over HTTPS only
     * @param {string} [options.sameSite='Strict'] - SameSite policy
     * @returns {void}
     * @throws {Error} When the name or value is not a string
     */
    set: function(name, value, options = {}) {
      if (typeof name !== 'string' || typeof value !== 'string') {
        throw new Error('[Utils.cookie.set] Name and value must be strings');
      }

      const defaultOptions = {
        days: 7,
        path: '/',
        domain: '',
        secure: true,
        sameSite: 'Strict'
      };
      const opts = {...defaultOptions, ...options};

      // Build cookie string
      let cookieStr = `${encodeURIComponent(name)}=${encodeURIComponent(value)}`;
      if (typeof opts.days === 'number' && opts.days !== 0) {
        const d = new Date();
        d.setTime(d.getTime() + (opts.days * 24 * 60 * 60 * 1000));
        cookieStr += `;expires=${d.toUTCString()}`;
      }
      if (opts.path) cookieStr += `;path=${opts.path}`;
      if (opts.domain) cookieStr += `;domain=${opts.domain}`;
      if (opts.secure) cookieStr += ';secure';
      if (opts.sameSite) cookieStr += `;samesite=${opts.sameSite}`;

      try {
        document.cookie = cookieStr;
      } catch (error) {
        console.error(`[Utils.cookie.set] Failed to set cookie ${name}:`, error);
      }
    },

    /**
     * Reads a cookie by name.
     *
     * @param {string} name - Cookie name
     * @returns {string|null} Value, or null when not set
     * @throws {Error} When the name is not a string
     */
    get: function(name) {
      if (typeof name !== 'string') {
        throw new Error('[Utils.cookie.get] Name must be a string');
      }

      const escapedName = name.replace(/([.*+?^${}()|[\]\\])/g, '\\$1');
      const regex = new RegExp(`(?:^|;)\\s*${escapedName}=([^;]*)`);
      const match = document.cookie.match(regex);
      return match ? decodeURIComponent(match[1]) : null;
    },

    /**
     * Removes a cookie by expiring it.
     *
     * The path and domain must match the ones it was written with, or the
     * browser keeps it.
     *
     * @param {string} name - Cookie name
     * @param {Object} [options={}] - Path and domain of the cookie
     * @returns {void}
     * @throws {Error} When the name is not a string
     */
    remove: function(name, options = {}) {
      if (typeof name !== 'string') {
        throw new Error('[Utils.cookie.remove] Name must be a string');
      }

      const removeOptions = {
        days: -1,
        path: options.path || '/',
        domain: options.domain || ''
      };
      this.set(name, '', removeOptions);
    },

    /**
     * Reports whether the browser accepts cookies, by writing a test cookie and
     * reading it back.
     *
     * @returns {boolean} True when cookies work
     */
    isEnabled() {
      try {
        document.cookie = 'cookietest=1';
        const result = document.cookie.indexOf('cookietest=') !== -1;
        document.cookie = 'cookietest=1; expires=Thu, 01-Jan-1970 00:00:01 GMT';
        return result;
      } catch (e) {
        return false;
      }
    }
  },

  url: {
    /**
     * Reads the query parameters of a URL as an object.
     *
     * @param {string} url - URL to read
     * @returns {Object} Parameters keyed by name
     */
    getQueryParams(url) {
      const params = {};
      new URL(url).searchParams.forEach((value, key) => {
        params[key] = value;
      });
      return params;
    },

    /**
     * Appends query parameters to a URL.
     *
     * Parameters are appended, so a name already present gains a second value
     * rather than replacing the first.
     *
     * @param {string} url - URL to extend
     * @param {Object} params - Parameters to add
     * @returns {string} The extended URL
     */
    addQueryParams(url, params) {
      const urlObj = new URL(url);
      Object.entries(params).forEach(([key, value]) => {
        urlObj.searchParams.append(key, value);
      });
      return urlObj.toString();
    }
  },

  path: {
    /**
     * Joins path segments with single slashes, dropping the empty ones.
     *
     * @param {...string} parts - Segments to join
     * @returns {string} Joined path, without leading or trailing slashes
     */
    join(...parts) {
      return parts
        .map(part => part.replace(/^\/+|\/+$/g, ''))
        .filter(part => part.length > 0)
        .join('/');
    },

    /**
     * Collapses runs of slashes into one.
     *
     * @param {string} path - Path to normalize
     * @returns {string} Normalized path
     */
    normalize(path) {
      return path.replace(/\/+/g, '/');
    },

    /**
     * Returns the last segment of a path; a trailing slash is ignored, so
     * '/path/to/dir/' gives 'dir'.
     *
     * @param {string} path - Path to read
     * @returns {string} Last segment
     */
    basename(path) {
      return path.replace(/\/+$/, '').split('/').pop();
    },

    /**
     * Returns a path without its last segment.
     *
     * @param {string} path - Path to read
     * @returns {string} Parent path
     */
    dirname(path) {
      return path.split('/').slice(0, -1).join('/');
    },

    /**
     * Returns the extension of a path, including the dot.
     *
     * @param {string} path - Path to read
     * @returns {string} Extension, empty when there is none
     */
    extname(path) {
      const basename = this.basename(path);
      const lastDotIndex = basename.lastIndexOf('.');
      return lastDotIndex === -1 ? '' : basename.slice(lastDotIndex);
    }
  },

  keyboard: {
    /**
     * Reports whether a key event matches a key and a set of modifier states.
     *
     * A modifier left out is not checked; one set to false requires it to be
     * up.
     *
     * @param {KeyboardEvent} event - Event to test
     * @param {string} key - Expected event.key
     * @param {Object} [modifiers={}] - {shift, ctrl, alt, meta} states to require
     * @returns {boolean} True when the event matches
     */
    isKey(event, key, modifiers = {}) {
      if (event.key !== key) return false;

      if (modifiers.shift !== undefined && event.shiftKey !== modifiers.shift) return false;
      if (modifiers.ctrl !== undefined && event.ctrlKey !== modifiers.ctrl) return false;
      if (modifiers.alt !== undefined && event.altKey !== modifiers.alt) return false;
      if (modifiers.meta !== undefined && event.metaKey !== modifiers.meta) return false;

      return true;
    },
    isEnter: (e) => e.key === 'Enter',
    isShiftEnter: (e) => e.key === 'Enter' && e.shiftKey,
    isCtrlEnter: (e) => e.key === 'Enter' && e.ctrlKey,
    isEscape: (e) => e.key === 'Escape',
    isTab: (e) => e.key === 'Tab',
    isShiftTab: (e) => e.key === 'Tab' && e.shiftKey,
    isArrow: (e) => ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)
  }
};

window.Utils = Utils;
